CREATE INDEX branches_session ON branches (session_id, agent_id);
CREATE INDEX context_samples_session ON context_samples (session_id, sampled_at);
CREATE INDEX human_events_session ON human_events (session_id, occurred_at);
CREATE INDEX loads_session ON loads (session_id, occurred_at);
CREATE INDEX pauses_session ON pauses (session_id, paused_at);
CREATE INDEX prompt_attachments_turn ON prompt_attachments (session_id, turn_id);
CREATE UNIQUE INDEX raw_events_envelope ON raw_events (envelope_id);
CREATE INDEX raw_events_session ON raw_events (session_id, received_at);
CREATE INDEX raw_events_source ON raw_events (source, received_at);
CREATE INDEX requests_session ON requests (session_id, request_id);
CREATE INDEX requests_turn ON requests (turn_id);
CREATE INDEX row_changes_session ON row_changes (session_id, seq);
CREATE INDEX segments_session ON segments (session_id, started_at);
CREATE INDEX steps_session ON steps (session_id, tool_use_id);
CREATE INDEX steps_session_outcome ON steps (session_id, outcome);
CREATE INDEX steps_turn ON steps (turn_id);
CREATE INDEX turns_prompt ON turns (session_id, prompt_id);
CREATE TABLE branches ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), agent_id TEXT, spawning_step_id INTEGER REFERENCES steps(id), agent_type TEXT, kind TEXT, -- user | internal (internal when agent_type is empty) started_at INTEGER, ended_at INTEGER, total_tokens INTEGER, token_source TEXT -- hook | telemetry | transcript , end_source TEXT);
CREATE TABLE compaction_files ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, at INTEGER NOT NULL, name TEXT NOT NULL, size_bytes INTEGER, reread INTEGER NOT NULL, UNIQUE (session_id, at, name) );
CREATE TABLE context_reports ( session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, model TEXT NOT NULL, window INTEGER NOT NULL, autocompact_buffer INTEGER, reported_at INTEGER NOT NULL, system_prompt INTEGER, mcp_instructions INTEGER, skills INTEGER, system_tools INTEGER, memory_files INTEGER, PRIMARY KEY (session_id, model) );
CREATE TABLE context_samples ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), request_id INTEGER REFERENCES requests(id), sampled_at INTEGER NOT NULL, context_tokens INTEGER NOT NULL, source TEXT NOT NULL -- telemetry | transcript );
CREATE TABLE finding_dismissals ( session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, finding_id TEXT NOT NULL, dismissed_at INTEGER NOT NULL, PRIMARY KEY (session_id, finding_id) );
CREATE TABLE forgotten ( session_id TEXT PRIMARY KEY, forgotten_at INTEGER NOT NULL );
CREATE TABLE human_events ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), turn_id INTEGER REFERENCES turns(id), step_id INTEGER REFERENCES steps(id), kind TEXT NOT NULL, -- prompt | permission_request | permission_decision | rejection | interrupt | question_answered | waiting | command | handback | notice occurred_at INTEGER NOT NULL, decision TEXT, -- accept | reject | accept_permanent decision_source TEXT, -- telemetry | inferred detail TEXT -- JSON summary (e.g. the chosen option label) );
CREATE TABLE loads ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), kind TEXT NOT NULL, -- skill | instructions name TEXT, trigger TEXT, -- user_slash | agent (skills) memory_type TEXT, -- User | Project (instruction files) file_path TEXT, occurred_at INTEGER NOT NULL, source TEXT NOT NULL -- hook | telemetry | transcript , size_bytes INTEGER, item_count INTEGER, names TEXT, branch_id INTEGER REFERENCES branches(id), parent_load_id INTEGER REFERENCES loads(id), line_count INTEGER);
CREATE TABLE meta ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE TABLE pauses ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), paused_at INTEGER NOT NULL, resumed_at INTEGER );
CREATE TABLE prompt_attachments ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), turn_id INTEGER NOT NULL REFERENCES turns(id), kind TEXT NOT NULL, -- image | file | prompt name TEXT, size_bytes INTEGER, line_count INTEGER -- prompt only );
CREATE TABLE purged ( session_id TEXT PRIMARY KEY, purged_at INTEGER NOT NULL );
CREATE TABLE raw_events ( id INTEGER PRIMARY KEY, source TEXT NOT NULL, -- hook | telemetry | transcript session_id TEXT, received_at INTEGER NOT NULL, event_at INTEGER, redaction_version INTEGER NOT NULL, body TEXT NOT NULL, -- JSON, post-redaction envelope_id TEXT -- the envelope's stable id, for hook payloads only );
CREATE TABLE request_shapes ( hash TEXT PRIMARY KEY, system_bytes INTEGER, tools TEXT -- JSON array of {name, bytes, mcp} );
CREATE TABLE requests ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), request_id TEXT, turn_id INTEGER REFERENCES turns(id), branch_id INTEGER REFERENCES branches(id), model TEXT, query_source TEXT, -- main | subagent | suggestion | title | compact input_tokens INTEGER, output_tokens INTEGER, cache_read_tokens INTEGER, cache_write_5m_tokens INTEGER, cache_write_1h_tokens INTEGER, token_source TEXT, -- telemetry | transcript started_at INTEGER, duration_ms INTEGER , effort TEXT, shape_hash TEXT REFERENCES request_shapes(hash), cache_lifetimes TEXT, context_edits TEXT);
CREATE TABLE row_changes ( seq INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, table_name TEXT NOT NULL, row_id INTEGER NOT NULL );
CREATE TABLE segments ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), kind TEXT NOT NULL, -- startup | resume | compact started_at INTEGER NOT NULL, context_tokens INTEGER, prompt_cache_likely_expired INTEGER );
CREATE TABLE session_conditions ( session_id TEXT PRIMARY KEY REFERENCES sessions(id), permission_modes TEXT, -- JSON array of mode names instruction_files TEXT, -- JSON array of paths enabled_plugins TEXT, -- JSON array of plugin names claude_code_version TEXT, sources_seen TEXT, -- JSON array: hook | telemetry | transcript updated_at INTEGER NOT NULL , hook_stats TEXT);
CREATE TABLE session_shapes ( session_id TEXT NOT NULL REFERENCES sessions(id), hash TEXT NOT NULL REFERENCES request_shapes(hash), PRIMARY KEY (session_id, hash) );
CREATE TABLE sessions ( id TEXT PRIMARY KEY, project_path TEXT, model TEXT, status TEXT NOT NULL DEFAULT 'live', -- live | paused | ended first_seen_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, joined_partway INTEGER NOT NULL DEFAULT 0 , tokens_partial INTEGER NOT NULL DEFAULT 0, end_seen INTEGER NOT NULL DEFAULT 1, host_pid INTEGER, host_started_at INTEGER);
CREATE TABLE steps ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), turn_id INTEGER REFERENCES turns(id), branch_id INTEGER REFERENCES branches(id), tool_use_id TEXT, tool_name TEXT NOT NULL, input_summary TEXT, -- JSON, post-redaction outcome TEXT, -- succeeded | failed | rejected | interrupted | open outcome_source TEXT, -- hook | telemetry | transcript | inferred | concluded | batch started_at INTEGER, ended_at INTEGER, duration_ms INTEGER, result_size INTEGER , result_request_id INTEGER REFERENCES requests(id), context_chars INTEGER, context_images INTEGER, async_launch INTEGER, saved_output_bytes INTEGER);
CREATE TABLE turns ( id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), prompt_id TEXT, sequence INTEGER NOT NULL, started_at INTEGER, ended_at INTEGER, prompt_text TEXT, flightpath_command INTEGER NOT NULL DEFAULT 0, prompt_chars INTEGER, prompt_lines INTEGER, image_count INTEGER, image_bytes INTEGER, end_source TEXT, UNIQUE (session_id, sequence) );
CREATE TRIGGER branches_changed AFTER UPDATE ON branches BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'branches', NEW.id); END;
CREATE TRIGGER compaction_files_inserted AFTER INSERT ON compaction_files BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'compaction_files', NEW.id); END;
CREATE TRIGGER loads_changed AFTER UPDATE ON loads BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'loads', NEW.id); END;
CREATE TRIGGER prompt_attachments_deleted AFTER DELETE ON prompt_attachments BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (OLD.session_id, 'prompt_attachments', OLD.turn_id); END;
CREATE TRIGGER prompt_attachments_inserted AFTER INSERT ON prompt_attachments BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'prompt_attachments', NEW.turn_id); END;
CREATE TRIGGER requests_changed AFTER UPDATE ON requests BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'requests', NEW.id); END;
CREATE TRIGGER session_shapes_inserted AFTER INSERT ON session_shapes BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'session_shapes', NEW.rowid); END;
CREATE TRIGGER steps_changed AFTER UPDATE ON steps BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'steps', NEW.id); END;
CREATE TRIGGER turns_changed AFTER UPDATE ON turns BEGIN INSERT INTO row_changes (session_id, table_name, row_id) VALUES (NEW.session_id, 'turns', NEW.id); END;
